// verify.mjs — differential test harness for the test14 Python→Node migration.
//
// Runs both the empirical reference executable (/workspace/dataset/test14_executable)
// and the Node reimplementation (/output/test14.mjs) over an embedded corpus of
// (--a, --b) input pairs, compares stdout bytes and exit codes, and prints a
// per-case PASS/FAIL report with exact first-difference details.
//
// Pure ESM, zero external dependencies. No RegExp is used anywhere.
//
// Usage: node /output/verify.mjs
// Exit code: 0 if every case matches, 1 otherwise.

import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';

const REF_EXE = '/workspace/dataset/test14_executable';
const NODE_EXE = process.execPath;
const NODE_SCRIPT = '/output/test14.mjs';
const MARKDOWN_IMPL = '/output/markdown.mjs';

// ---------------------------------------------------------------------------
// Corpus
// ---------------------------------------------------------------------------
// Each case: { name, a, b }.  Values are passed as-is through execFileSync
// argument arrays (never through a shell), so any bytes are safe here.
const corpus = [
  // --- The 4 documented samples -------------------------------------------
  {
    name: 'table-like text',
    a: '| Name | Age |\n| ---- | --- |\n| Ann  | 30  |',
    b: '| City | Pop |\n| ---- | --- |\n| Oslo | 700 |',
  },
  {
    name: 'CJK paragraphs',
    a: '这是第一段中文文本。\n这是第二行。',
    b: '日本語のテキストです。\n二行目です。',
  },
  {
    name: 'ordered list vs bullet list with CJK fruit',
    a: '1. 苹果\n2. 香蕉\n3. 橙子',
    b: '- 苹果\n- 香蕉\n- 橙子',
  },
  {
    name: 'fenced bash block vs fenced CJK text block',
    a: '```bash\necho hello\nls -la\n```',
    b: '```\n这是代码块\n第二行\n```',
  },

  // --- Edge cases ----------------------------------------------------------
  { name: 'empty a', a: '', b: 'non-empty b' },
  { name: 'empty b', a: 'non-empty a', b: '' },
  { name: 'both empty', a: '', b: '' },
  {
    name: 'entities and angle brackets',
    a: 'a & b < c > d',
    b: 'already &amp; escaped &lt;tag&gt; &#169;',
  },
  {
    name: 'emphasis markers',
    a: '*x* and **y**',
    b: '_z_ and __w__',
  },
  {
    name: 'emphasis mixed with text',
    a: 'plain *em* plain **strong** plain',
    b: 'a_b_c and x**y**z',
  },
  {
    name: 'link',
    a: '[t](http://u)',
    b: 'see [the docs](https://example.com/path?q=1&r=2) now',
  },
  {
    name: 'image',
    a: '![alt](http://img/x.png)',
    b: 'pic: ![a *b*](img.png "title")',
  },
  {
    name: 'inline code single backticks',
    a: 'use `foo()` here',
    b: '`code with <angle> & amp`',
  },
  {
    name: 'inline code double backticks',
    a: '``code with `tick` inside``',
    b: '`` spaced ` code ``',
  },
  {
    name: 'inline code triple backticks',
    a: '```python\ndef hello():\n    print(1)\n```',
    b: 'text ```js\nlet x = 1;\n``` more',
  },
  {
    name: 'inline code odd spacing',
    a: '`  padded  `',
    b: '`` ` ``',
  },
  {
    name: 'nested list 2-space indent',
    a: '- a\n  - b\n  - c\n- d',
    b: '1. x\n  1. y\n  2. z\n2. w',
  },
  {
    name: 'nested list 4-space indent',
    a: '- a\n    - b\n    - c\n- d',
    b: '1. x\n    1. y\n    2. z\n2. w',
  },
  {
    name: 'mixed ordered list numbering',
    a: '1. one\n3. three\n7. seven',
    b: '7. seven\n3. three\n1. one',
  },
  {
    name: 'headers inside a',
    a: '# H1 Title\n\nSome text',
    b: '### H3 Title\n\ntail',
  },
  {
    name: 'header with closing hashes',
    a: '### Closed ###',
    b: '# Also closed #\n\ntext',
  },
  {
    name: 'blockquotes',
    a: '> quoted line\n> second quoted',
    b: '> quote with *em*\n\nafter',
  },
  {
    name: 'horizontal rules',
    a: 'above\n\n---\n\nbelow',
    b: '***\n\ntext after stars',
  },
  {
    name: 'raw HTML line',
    a: '<div>hi</div>',
    b: 'before\n\n<span>inline</span>\n\nafter',
  },
  {
    name: 'leading/trailing spaces',
    a: '   spaced in and out   ',
    b: '\t tabbed start',
  },
  {
    name: 'blank lines inside',
    a: 'para one\n\n\n\npara two',
    b: '\n\nleading blank lines\n\ntext',
  },
  {
    name: 'trailing blank lines',
    a: 'text\n\n\n',
    b: 'other text\n\n',
  },
  {
    name: 'unicode and emoji',
    a: 'emoji 🎉🚀 and CJK 汉字 mixed',
    b: 'ümlauts éè ê, 中文, 한국어, العربية',
  },
  {
    name: 'very long paragraph single newlines',
    a: longParagraph('alpha', 40),
    b: longParagraph('beta', 55),
  },
  {
    name: 'list then paragraph',
    a: '- item\n\nparagraph after',
    b: 'paragraph before\n\n- item one\n- item two',
  },
  {
    name: 'multiple block kinds in one arg',
    a: '# Head\n\npara *em*\n\n- li1\n- li2\n\n> quote\n\n---\n\ntail `code`',
    b: '1. one\n2. two\n\n### Sub\n\nfinal [link](http://x)',
  },
  {
    name: 'angle-bracket autolink-ish text',
    a: 'visit <http://example.com> now',
    b: 'mail <me@example.com> here',
  },
  {
    name: 'hard line breaks (trailing two spaces)',
    a: 'line one  \nline two',
    b: 'no break\nnext line',
  },
  {
    name: 'setext-style underline',
    a: 'Setext Title\n=============',
    b: 'Sub Title\n---------',
  },
  {
    name: 'backslash escapes',
    a: 'escape \\*not em\\* and \\\\ backslash',
    b: '\\`not code\\` and \\[not link\\]',
  },
  {
    name: 'strikethrough-ish tildes (not an extension)',
    a: '~~struck~~ text',
    b: '~one~ tilde',
  },
  {
    name: 'numeric entities',
    a: '&#72;&#105; numeric',
    b: '&#x41;&#x42; hex',
  },
  {
    name: 'code with blank line inside backticks',
    a: '``line1\n\nline2``',
    b: '`single`',
  },
];

function longParagraph(word, lines) {
  const parts = [];
  for (let i = 0; i < lines; i++) {
    parts.push(word + ' sentence number ' + i + ' with some words to fill the line out.');
  }
  return parts.join('\n');
}

// ---------------------------------------------------------------------------
// Escaping / diff helpers (string scanning only — no RegExp)
// ---------------------------------------------------------------------------

// Escape a string into a printable representation: control chars, quotes,
// backslashes and non-ASCII become escape sequences.
function escapeStr(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x5c) out += '\\\\';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c === 0x09) out += '\\t';
    else if (c === 0x22) out += '\\"';
    else if (c >= 0x20 && c < 0x7f) out += s[i];
    else if (c <= 0xff) out += '\\x' + c.toString(16).padStart(2, '0');
    else out += '\\u' + c.toString(16).padStart(4, '0');
  }
  return out;
}

function escapeBuffer(buf) {
  return escapeStr(buf.toString('utf8'));
}

// Find the first byte offset where two buffers differ.
// Returns -1 if identical.
function firstDiffOffset(b1, b2) {
  const n = Math.min(b1.length, b2.length);
  for (let i = 0; i < n; i++) {
    if (b1[i] !== b2[i]) return i;
  }
  if (b1.length !== b2.length) return n;
  return -1;
}

// Split a buffer into lines (keeping no terminators), returning
// [{text, byteStart}] so we can map byte offsets to line numbers.
function splitLines(buf) {
  const s = buf.toString('utf8');
  const lines = [];
  let start = 0;
  let byteStart = 0;
  for (let i = 0; i <= s.length; i++) {
    if (i === s.length || s[i] === '\n') {
      lines.push({ text: s.slice(start, i), byteStart });
      byteStart += Buffer.byteLength(s.slice(start, i), 'utf8') + 1;
      start = i + 1;
    }
  }
  // If the string ends without a trailing newline we pushed the final line
  // already; if it is empty, drop the artificial extra empty line.
  if (lines.length > 0 && lines[lines.length - 1].text === '' && s.length > 0 && s[s.length - 1] === '\n') {
    lines.pop();
  }
  if (s.length === 0) return [];
  return lines;
}

// Render a context window of `radius` bytes around `offset` as escaped text,
// with a caret marking the exact offset.
function byteContext(buf, offset, radius) {
  const start = Math.max(0, offset - radius);
  const end = Math.min(buf.length, offset + radius);
  const before = buf.slice(start, offset).toString('utf8');
  const after = buf.slice(offset, end).toString('utf8');
  const caretPad = escapeStr(before).length;
  let marker = '';
  for (let i = 0; i < caretPad; i++) marker += ' ';
  marker += '^';
  const pre = start > 0 ? '...' : '';
  const post = end < buf.length ? '...' : '';
  return pre + escapeStr(before) + escapeStr(after.slice(0, 0)) + escapeStr(after) + post + '\n'
    + ' '.repeat(pre.length) + marker;
}

// Build a human-readable first-difference report between expected and actual.
function diffReport(expected, actual) {
  const lines = [];
  if (expected.equals(actual)) return '  (outputs identical)';
  const off = firstDiffOffset(expected, actual);
  const expByte = off < expected.length ? expected[off] : null;
  const actByte = off < actual.length ? actual[off] : null;
  lines.push('  first byte difference at offset ' + off
    + ' (expected length ' + expected.length + ', actual length ' + actual.length + ')');
  lines.push('  expected byte: ' + (expByte === null ? '<EOF>' : '0x' + expByte.toString(16).padStart(2, '0'))
    + '  actual byte: ' + (actByte === null ? '<EOF>' : '0x' + actByte.toString(16).padStart(2, '0')));

  // Locate the differing line in each output for a side-by-side excerpt.
  const expLines = splitLines(expected);
  const actLines = splitLines(actual);
  const expLineIdx = lineIndexForOffset(expLines, off);
  const actLineIdx = lineIndexForOffset(actLines, off);
  lines.push('  expected line ' + (expLineIdx + 1) + ': ' + escapeStr(lineAt(expLines, expLineIdx)));
  lines.push('  actual   line ' + (actLineIdx + 1) + ': ' + escapeStr(lineAt(actLines, actLineIdx)));

  lines.push('  expected context:');
  lines.push('  ' + indentBlock(byteContext(expected, off, 60)));
  lines.push('  actual   context:');
  lines.push('  ' + indentBlock(byteContext(actual, off, 60)));
  return lines.join('\n');
}

function lineIndexForOffset(lines, byteOffset) {
  let idx = 0;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].byteStart <= byteOffset) idx = i;
    else break;
  }
  return idx;
}

function lineAt(lines, idx) {
  if (idx < 0 || idx >= lines.length) return '<no line>';
  return lines[idx].text;
}

function indentBlock(block) {
  // block may contain a newline (context line + caret line); indent every line.
  const s = block;
  let out = '';
  let atStart = true;
  for (let i = 0; i < s.length; i++) {
    if (atStart && s[i] !== '\n') { out += ''; atStart = false; }
    if (s[i] === '\n') { out += '\n  '; atStart = true; }
    else out += s[i];
  }
  return out;
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

// Run a command, capturing stdout bytes and exit code without throwing.
function runCapture(cmd, args) {
  try {
    const stdout = execFileSync(cmd, args, { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
    return { stdout, code: 0, error: null };
  } catch (e) {
    return {
      stdout: e.stdout ? Buffer.from(e.stdout) : Buffer.alloc(0),
      code: typeof e.status === 'number' ? e.status : -1,
      error: e.message,
    };
  }
}

function main() {
  // Check teammate files first: harness must report "ready but awaiting" if
  // the implementation does not exist yet.
  const missing = [];
  if (!existsSync(NODE_SCRIPT)) missing.push(NODE_SCRIPT);
  if (!existsSync(MARKDOWN_IMPL)) missing.push(MARKDOWN_IMPL);
  if (!existsSync(REF_EXE)) missing.push(REF_EXE);

  if (missing.length > 0) {
    console.log('HARNESS NOT RUNNABLE — missing file(s):');
    for (const m of missing) console.log('  - ' + m);
    console.log('');
    console.log('The harness (' + process.argv[1] + ') is written and ready, but is');
    console.log('awaiting the implementation files from the other teammates.');
    process.exit(1);
  }

  let pass = 0;
  let fail = 0;
  const failures = [];

  for (let i = 0; i < corpus.length; i++) {
    const tc = corpus[i];
    const args = ['--a', tc.a, '--b', tc.b];
    const expected = runCapture(REF_EXE, args);
    const actual = runCapture(NODE_EXE, [NODE_SCRIPT, ...args]);

    const stdoutSame = expected.stdout.equals(actual.stdout);
    const codeSame = expected.code === actual.code;

    if (stdoutSame && codeSame) {
      pass++;
      console.log('PASS [' + (i + 1) + '/' + corpus.length + '] ' + tc.name);
    } else {
      fail++;
      failures.push(tc.name);
      console.log('FAIL [' + (i + 1) + '/' + corpus.length + '] ' + tc.name);
      console.log('  input --a: ' + escapeStr(tc.a));
      console.log('  input --b: ' + escapeStr(tc.b));
      if (!codeSame) {
        console.log('  exit code mismatch: expected ' + expected.code + ', actual ' + actual.code);
        if (actual.error) console.log('  actual stderr/error: ' + actual.error);
      }
      if (!stdoutSame) {
        console.log(diffReport(expected.stdout, actual.stdout));
      }
    }
  }

  console.log('');
  console.log('===================================================================');
  console.log('SUMMARY: ' + pass + ' passed, ' + fail + ' failed, ' + corpus.length + ' total');
  if (fail > 0) {
    console.log('Failed cases:');
    for (const f of failures) console.log('  - ' + f);
  }
  console.log('===================================================================');
  process.exit(fail === 0 ? 0 : 1);
}

main();

