// Render a context window of `radius` bytes around `offset` as escaped text,
// with a caret marking the exact offset. The window edges are nudged to UTF-8
// character boundaries so no replacement chars (U+FFFD) appear in the output.
function byteContext(buf, offset, radius) {
  let start = Math.max(0, offset - radius);
  let end = Math.min(buf.length, offset + radius);
  // A UTF-8 continuation byte has the form 10xxxxxx; skip forward/backward
  // past any of them so slices begin/end on a character boundary.
  while (start < offset && (buf[start] & 0xc0) === 0x80) start++;
  while (end > offset && (buf[end] & 0xc0) === 0x80) end--;
  const before = buf.slice(start, offset).toString('utf8');
  const after = buf.slice(offset, end).toString('utf8');
  const caretPad = escapeStr(before).length;
  let marker = '';
  for (let i = 0; i < caretPad; i++) marker += ' ';
  marker += '^';
  const pre = start > 0 ? '...' : '';
  const post = end < buf.length ? '...' : '';
  return pre + escapeStr(before) + escapeStr(after) + post + '\n'
    + ' '.repeat(pre.length) + marker;
}

